/* Generated from web/panel.html. */
static const char panel_html[] = "<!doctype html><html lang=\"pt-BR\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>C\u00e2mera local</title>\n<style>body{font:16px system-ui;background:#101920;color:#e9f3f5;max-width:1050px;margin:auto;padding:24px}h1{margin-bottom:6px}p{color:#abc1ca}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:16px}section{background:#1a2933;padding:20px;border:1px solid #2b414d;border-radius:14px}button,input,select{font:inherit;padding:9px;border-radius:7px;border:1px solid #48616e;margin:4px;background:#10212b;color:inherit}button{cursor:pointer;background:#164d61}button:disabled{opacity:.4}label{display:block;margin:8px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:380px;overflow:auto;background:#0b151c;padding:12px}small{color:#b9cdd4}.wide{grid-column:1/-1}#status{min-height:24px;color:#7ddbd2}</style>\n<h1>C\u00e2mera local <small>v3 \u00b7 experimental</small></h1><p>Firmware e drivers originais. Painel na rede local, sem iCSee ou conta na nuvem.</p>\n<section><label>Usu\u00e1rio da c\u00e2mera <input id=\"user\" value=\"\" autocomplete=\"username\"></label><label>Senha do dispositivo <input id=\"password\" type=\"password\" autocomplete=\"current-password\"></label><small>A credencial fica apenas nesta p\u00e1gina enquanto ela estiver aberta. Feche a aba para encerrar.</small><button onclick=\"connect()\">Verificar conex\u00e3o</button><button onclick=\"document.getElementById('password').value='';out.textContent=''\">Limpar credencial</button></section><p id=\"status\" role=\"status\"></p>\n<main><section><h2>Cart\u00e3o e grava\u00e7\u00f5es</h2><button onclick=\"storage()\">Capacidade e estado</button><p id=\"capacity\">Consulte o estado do cart\u00e3o.</p><label>Data <input type=\"date\" id=\"date\"></label><button onclick=\"files(true)\">Consultar grava\u00e7\u00f5es do dia</button><button id=\"morefiles\" onclick=\"files(false)\" disabled>Pr\u00f3ximo lote</button><p id=\"filecount\"></p><div id=\"records\"></div><small>Busca por data no cart\u00e3o da c\u00e2mera. Reprodu\u00e7\u00e3o e exporta\u00e7\u00e3o n\u00e3o est\u00e3o inclu\u00eddas nesta vers\u00e3o.</small></section>\n<section><h2>Movimento e posi\u00e7\u00f5es</h2><div><button onclick=\"move('Up')\">\u2191</button><button onclick=\"move('Left')\">\u2190</button><button onclick=\"move('Right')\">\u2192</button><button onclick=\"move('Down')\">\u2193</button></div><small>Cada clique solicita um movimento de 250 ms seguido de parada.</small><label>Posi\u00e7\u00e3o <input type=\"number\" id=\"preset\" value=\"1\" min=\"1\" max=\"16\"></label><button onclick=\"preset('SetPreset')\">Salvar posi\u00e7\u00e3o atual</button><button onclick=\"preset('GotoPreset')\">Ir \u00e0 posi\u00e7\u00e3o</button><button onclick=\"read('Uart.PTZPreset')\">Consultar posi\u00e7\u00f5es</button></section>\n<section><h2>Grava\u00e7\u00e3o no cart\u00e3o</h2><button onclick=\"read('Record')\">Consultar regras atuais</button><select id=\"mode\"><option value=\"ManualRecord\">Cont\u00ednua</option><option value=\"ConfigRecord\">Usar agenda</option><option value=\"ClosedRecord\">Desativada</option></select><button onclick=\"patch('Record','RecordMode',val('mode'))\">Aplicar modo</button><label>Agenda di\u00e1ria <input id=\"start\" type=\"time\" value=\"00:00\"> at\u00e9 <input id=\"end\" value=\"24:00\" size=\"5\" maxlength=\"5\"></label><label><input id=\"motion\" type=\"checkbox\"> Somente movimento no per\u00edodo</label><small>Aplicar agenda substitui os per\u00edodos dos sete dias por este per\u00edodo di\u00e1rio. Detec\u00e7\u00e3o de movimento precisa estar habilitada no firmware.</small><button onclick=\"schedule()\">Aplicar agenda aos sete dias</button></section>\n<section><h2>Noite e ilumina\u00e7\u00e3o</h2><button onclick=\"read('Camera.Param')\">Consultar vis\u00e3o noturna</button><button onclick=\"read('Camera.ParamEx')\">Consultar ilumina\u00e7\u00e3o</button><label>Vis\u00e3o <select id=\"night\"><option value=\"0x00000000\">Autom\u00e1tica</option><option value=\"0x00000001\">Colorida</option><option value=\"0x00000002\">Preto e branco</option><option value=\"0x00000003\">Inteligente</option></select></label><button onclick=\"patch('Camera.Param','DayNightColor',val('night'))\">Aplicar vis\u00e3o</button><button onclick=\"api('light',{action:'KeepOpen'})\">Acender luz branca</button><button onclick=\"api('light',{action:'Close'})\">Apagar luz branca</button><small>Modos dependem do suporte real do hardware; suporte e comportamento dependem do modelo.</small></section>\n<section class=\"wide\"><h2>Diagn\u00f3stico</h2><button onclick=\"api('health',{})\">Estado da extens\u00e3o</button><button onclick=\"read('WorkState')\">Estado de funcionamento</button><button onclick=\"read('Simplify.Encode')\">Configura\u00e7\u00e3o de v\u00eddeo</button><small>N\u00e3o h\u00e1 comandos de flash, formata\u00e7\u00e3o, rein\u00edcio ou restaura\u00e7\u00e3o de f\u00e1brica neste painel.</small><pre id=\"out\" aria-live=\"polite\">Aguardando consulta.</pre></section></main>\n<script>\nconst out=document.getElementById('out'),status=document.getElementById('status');let busy=false;const val=id=>document.getElementById(id).value;\nasync function api(path,data){if(busy)return;busy=true;status.textContent='Consultando c\u00e2mera\u2026';document.querySelectorAll('button').forEach(b=>b.disabled=true);try{const auth=btoa(unescape(encodeURIComponent(val('user')+':'+val('password'))));const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Localmod':'1','Authorization':'Basic '+auth},body:JSON.stringify(data),cache:'no-store'});const text=await r.text();if(!r.ok)throw Error(text);const j=JSON.parse(text);out.textContent=JSON.stringify(j,null,2);status.textContent=j.erro?'Falha: '+j.erro:j.Ret===119?'Nenhuma grava\u00e7\u00e3o encontrada no per\u00edodo.':j.Ret!==undefined&&![100,110,111,150].includes(j.Ret)?'Comando recusado pelo firmware: '+j.Ret:'Resposta recebida. Confira o resultado abaixo.';return j;}catch(e){status.textContent='Falha: '+e.message;}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);}}\nasync function read(name){const j=await api('read',{name});if(j?.Record?.[0]?.RecordMode)document.getElementById('mode').value=j.Record[0].RecordMode;if(j?.['Camera.Param']?.[0]?.DayNightColor)document.getElementById('night').value=j['Camera.Param'][0].DayNightColor;return j;}function move(d){return api('ptz',{direction:'Direction'+d});}function preset(action){return api('preset',{action,number:Number(val('preset'))});}function patch(name,field,value){return api('patch',{name,field,value});}let cursor='',limit='',seen=new Set();async function connect(){const j=await read('SystemInfo');if(j?.Ret===100){await storage();await read('Record');await read('Camera.Param');}}async function storage(){const j=await read('StorageInfo');if(j?.Ret!==100)return;let total=0,free=0;for(const d of j.StorageInfo||[])for(const p of d.Partition||[]){total+=Number(p.TotalSpace)||0;free+=Number(p.RemainSpace)||0;}document.getElementById('capacity').textContent=total?free.toLocaleString('pt-BR')+' MB livres de '+total.toLocaleString('pt-BR')+' MB.':'Cart\u00e3o n\u00e3o inicializado ou indispon\u00edvel para grava\u00e7\u00e3o.';}async function files(reset=true){const d=val('date'),more=document.getElementById('morefiles');if(!d)return;if(reset){cursor=d+' 00:00:00';limit=d+' 23:59:59';seen.clear();document.getElementById('records').replaceChildren();}if(!cursor)return;const before=cursor,j=await api('files',{begin:cursor,end:limit});const list=Array.isArray(j?.OPFileQuery)?j.OPFileQuery:[];for(const f of list){if(!f.FileName||seen.has(f.FileName))continue;seen.add(f.FileName);const row=document.createElement('p');row.textContent=(f.BeginTime||'')+' \u2192 '+(f.EndTime||'')+' \u00b7 '+(f.FileLength||0)+' KB';row.title=f.FileName;document.getElementById('records').append(row);}const last=list.at(-1);cursor=list.length>=64&&(last?.BeginTime>before)?last.BeginTime:'';more.disabled=!cursor;document.getElementById('filecount').textContent=seen.size+' grava\u00e7\u00f5es encontradas'+(cursor?' \u00b7 h\u00e1 mais resultados.':'.');}function schedule(){api('schedule',{start:val('start'),end:val('end'),motion:document.getElementById('motion').checked,days:[true,true,true,true,true,true,true]});}document.getElementById('date').value=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);\n</script></html>\n";
